  const m = /^(?:([^:/?#]+):)?(?:\/\/([^/?#]*))?([^?#]*)(?:\?([^#]*))?(?:#(.*))?$/s.exec(s)
  const r = { scheme: m[1], authority: m[2], path: m[3], query: m[4], fragment: m[5] }
  if (r.authority !== undefined) {
    let a = r.authority
    const at = a.lastIndexOf('@')
    if (at >= 0) { r.userinfo = a.slice(0, at); a = a.slice(at + 1) }
    const rb = a.lastIndexOf(']')
    const colon = a.indexOf(':', rb + 1)
    if (colon >= 0) { r.port = a.slice(colon + 1); a = a.slice(0, colon) }
    r.host = a
  }
  return r
}

