    if (o.userinfo !== undefined) s += o.userinfo + '@'
    s += o.host
    if (o.port !== undefined) s += ':' + o.port
  }
  s += o.path
  if (o.query !== undefined) s += '?' + o.query
  if (o.fragment !== undefined) s += '#' + o.fragment
  return s
