    Object.assign(t, r); t.path = removeDots(r.path)
  } else if (r.authority !== undefined) {
    withAuth(t, r); t.scheme = b.scheme; t.path = removeDots(r.path); t.query = r.query
  } else {
    withAuth(t, b); t.scheme = b.scheme
    if (r.path === '') { t.path = b.path; t.query = r.query !== undefined ? r.query : b.query }
    else {
      if (r.path.startsWith('/')) t.path = removeDots(r.path)
      else {
        let m
        if (b.authority !== undefined && b.path === '') m = '/' + r.path
        else { const i = b.path.lastIndexOf('/'); m = i < 0 ? r.path : b.path.slice(0, i + 1) + r.path }
        t.path = removeDots(m)
      }
      t.query = r.query
    }
  }
  t.fragment = r.fragment
  return t
}

const chunks = []
process.stdin.on('data', (c) => chunks.push(c))
process.stdin.on('end', () => {
  const lines = Buffer.concat(chunks).toString('utf8').split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const out = []
  try {
    lines.forEach((line, idx) => {
      const n = idx + 1
      if (mode[0] === 'normalize') {
        const r = parse(line)
        checkPct(r, n)
        out.push(serialize(normalize(r)))
      } else {
        const sp = line.indexOf(' ')
        if (sp < 0) throw new Fail(`error: line ${n}: expected a base and a reference`)
        const b = parse(line.slice(0, sp))
        if (b.scheme === undefined) throw new Fail(`error: line ${n}: the base has no scheme`)
        const r = parse(line.slice(sp + 1))
        checkPct(b, n)
        checkPct(r, n)
        out.push(serialize(normalize(resolve(b, r))))
      }
    })
  } catch (e) {
    if (!(e instanceof Fail)) throw e
    process.stderr.write(e.message + '\n')
    process.exit(2)
  }
  process.stdout.write(out.map((l) => l + '\n').join(''))
